    let doublestar = doublestar?;

    let mut edits = Vec::new();

    // Remove the `**`, any parentheses wrapping the dictionary, and the
    // dictionary's opening brace. Comments and other trivia between these
    // tokens are preserved.
    let mut opened = false;
    for tok in SimpleTokenizer::starts_at(doublestar.start(), source) {
        let kind = tok.kind();
        if kind.is_trivia() {
            continue;
        }
        match kind {
            SimpleTokenKind::DoubleStar | SimpleTokenKind::LParen => {
                edits.push(Edit::range_deletion(tok.range()));
            }
            SimpleTokenKind::LBrace if tok.start() == dict.start() => {
                edits.push(Edit::range_deletion(tok.range()));
                opened = true;
                break;
            }
            _ => break,
        }
    }
    if !opened {
        return None;
    }

    if let Some(last) = dict.iter_values().last() {
        let last_end = last.end();
        let mut closed = false;
        for tok in SimpleTokenizer::starts_at(last_end, source) {
            let kind = tok.kind();
            if kind.is_trivia() {
                continue;
            }
            match kind {
                SimpleTokenKind::Comma if !closed => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                SimpleTokenKind::RBrace if !closed => {
                    edits.push(Edit::range_deletion(tok.range()));
                    closed = true;
                }
                SimpleTokenKind::RParen if closed => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                _ => {
                    if closed {
                        break;
                    }
                }
            }
        }
    } else {
        // The dictionary is empty, so remove its closing brace (and any
        // wrapping parentheses) along with a following comma, if present.
        let mut closed = false;
        for tok in SimpleTokenizer::starts_at(dict.start() + TextSize::from(1), source) {
            let kind = tok.kind();
            if kind.is_trivia() {
                continue;
            }
            match kind {
                SimpleTokenKind::RBrace if !closed => {
                    edits.push(Edit::range_deletion(tok.range()));
                    closed = true;
                }
                SimpleTokenKind::RParen if closed => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                SimpleTokenKind::Comma if closed => {
                    edits.push(Edit::range_deletion(tok.range()));
                    break;
                }
                _ => {
                    if closed {
                        break;
                    }
                }
            }
        }
        if !closed {
            return None;
        }
    }

    let first = edits.remove(0);
    Some(Fix::safe_edits(first, edits))
}

